using CP.ProRoad;
using UnityEditor;
using UnityEngine;

namespace ProRoadMeshTools {

	/// <summary>
	/// ProRoadが生成したメッシュにMeshColliderを追加します。
	/// Adds MeshCollider components to meshes generated by ProRoad.
	/// </summary>
	internal static class ProRoadMeshColliderUtility {

		/// <summary>
		/// 親オブジェクト直下のProRoadにある生成メッシュへMeshColliderを追加します。
		/// Adds MeshCollider components to generated meshes for ProRoad components directly under a parent object.
		/// </summary>
		internal static void AddMeshCollidersToRoads( GameObject _parent, PhysicsMaterial _physicsMaterial ) {
			if ( _parent == null ) return;

			Undo.IncrementCurrentGroup( );
			int undoGroup = Undo.GetCurrentGroup( );
			Undo.SetCurrentGroupName( "Add ProRoad Mesh Colliders" );
			try {
				for ( int i = 0; i < _parent.transform.childCount; i++ ) {
					Transform child = _parent.transform.GetChild( i );
					ProRoad road = child.GetComponent<ProRoad>( );
					if ( road != null ) AddMeshCollidersToRoadMeshes( road, _physicsMaterial );
				}
			}
			finally {
				Undo.CollapseUndoOperations( undoGroup );
			}
		}

		/// <summary>
		/// 1つのProRoadにある生成メッシュへMeshColliderを追加します。
		/// Adds MeshCollider components to generated meshes for one ProRoad component.
		/// </summary>
		internal static void AddMeshCollidersToRoad( ProRoad _road, PhysicsMaterial _physicsMaterial ) {
			if ( _road == null ) return;

			Undo.IncrementCurrentGroup( );
			int undoGroup = Undo.GetCurrentGroup( );
			Undo.SetCurrentGroupName( "Add ProRoad Mesh Colliders" );
			try {
				AddMeshCollidersToRoadMeshes( _road, _physicsMaterial );
			}
			finally {
				Undo.CollapseUndoOperations( undoGroup );
			}
		}

		/// <summary>
		/// ProRoadのMeshes階層にある各メッシュへMeshColliderを追加します。
		/// Adds a MeshCollider component to each mesh in a ProRoad Meshes hierarchy.
		/// </summary>
		private static void AddMeshCollidersToRoadMeshes( ProRoad _road, PhysicsMaterial _physicsMaterial ) {
			Transform meshesParent = _road.transform.Find( "Meshes" );
			if ( meshesParent == null ) return;

			for ( int i = 0; i < meshesParent.childCount; i++ ) {
				Transform child = meshesParent.GetChild( i );
				if ( child == null ) continue;

				AddMeshCollider( child.gameObject, _physicsMaterial );
				Debug.Log( "Processed ProRoad mesh: " + child.gameObject.name, child.gameObject );
			}
		}

		/// <summary>
		/// GameObjectへMeshColliderを追加し、指定されていればPhysicsMaterialを割り当てます。
		/// Adds a MeshCollider to a GameObject and assigns the specified PhysicsMaterial when provided.
		/// </summary>
		private static MeshCollider AddMeshCollider( GameObject _gameObject, PhysicsMaterial _physicsMaterial ) {
			MeshCollider meshCollider = _gameObject.GetComponent<MeshCollider>( );
			if ( meshCollider == null ) meshCollider = Undo.AddComponent<MeshCollider>( _gameObject );

			if ( _physicsMaterial != null && meshCollider.sharedMaterial != _physicsMaterial ) {
				Undo.RecordObject( meshCollider, "Assign ProRoad Physics Material" );
				meshCollider.sharedMaterial = _physicsMaterial;
				PrefabUtility.RecordPrefabInstancePropertyModifications( meshCollider );
				EditorUtility.SetDirty( meshCollider );
			}

			return meshCollider;
		}
	}
}
